186	/**
187	 * Resolve a plugin by either database ID or plugin key.
188	 *
189	 * Lookup order:
190	 * - UUID-like IDs: getById first, then getByKey.
191	 * - Scoped package keys (e.g. "@scope/name"): getByKey only, never getById.
192	 * - Other non-UUID IDs: try getById first (test/memory registries may allow this),
193	 *   then fallback to getByKey. Any UUID parse error from getById is ignored.
194	 *
195	 * @param registry - The plugin registry service instance
196	 * @param pluginId - Either a database UUID or plugin key (manifest id)
197	 * @returns Plugin record or null if not found
198	 */
199	async function resolvePlugin(
200	  registry: ReturnType<typeof pluginRegistryService>,
201	  pluginId: string,
202	) {
203	  const isUuid = UUID_REGEX.test(pluginId);
204	  const isScopedPackageKey = pluginId.startsWith("@") || pluginId.includes("/");
205	
206	  // Scoped package IDs are valid plugin keys but invalid UUIDs.
207	  // Skip getById() entirely to avoid Postgres uuid parse errors.
208	  if (isScopedPackageKey && !isUuid) {
209	    return registry.getByKey(pluginId);
210	  }
211	
212	  try {
213	    const byId = await registry.getById(pluginId);
214	    if (byId) return byId;
